def transform(g):
 h,w=len(g),len(g[0]); rows=[i for i,r in enumerate(g) if all(x==5 for x in r)]; cols=[j for j in range(w) if all(g[i][j]==5 for i in range(h))]
 out=[r[:] for r in g]
 if rows and cols:
  r,c=rows[0],cols[0]; mh,mw=h-r-1,w-c-1
  for i in range(h):
   if i==r: continue
   for j in range(w):
    if j!=c: out[i][j]=g[r+1+(i%mh)][c+1+(j%mw)]
 elif rows:
  r=rows[0]
  for k in range(min(r,h-r-1)): out[r-1-k]=g[r+1+k][:]
 return out
